// Página pública de seleção de fotos (/selecao/:slug) — aba separada de "Entregas" (server/
// deliveryPage.js), pedido do usuário em 17/09/2026 inspirado no site Alboom: antes de editar de
// verdade, o cliente vê as fotos em baixa resolução e com marca d'água (ver server/upload.js,
// saveSelectionPhoto), marca as favoritas numa grade e envia — o fotógrafo edita só as escolhidas
// depois (painel: aba "Revisão" em /admin/selecao/:id/revisao, com lista pronta pra exportar pro
// Lightroom/Finder/Explorer). Ao contrário da entrega (formato "story", tela cheia), aqui é uma
// grade normal — o objetivo é comparar várias fotos lado a lado pra escolher, não "assistir" uma
// atrás da outra.
import { escapeHtml } from './util.js';
import { ASSET_VERSION } from './assetVersion.js';

const PUBLIC_API_BASE = process.env.PUBLIC_API_BASE || '';

const CASE_CSS = `
  @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600&family=Inter:wght@400;500;600&display=swap');
    *{box-sizing:border-box;}
      body{margin:0;background:#0b0a0d;color:#f1ede4;font-family:'Inter',system-ui,sans-serif;line-height:1.6;-webkit-font-smoothing:antialiased;padding-bottom:96px;}
        a{color:inherit;}
          .container{max-width:1180px;margin:0 auto;padding:0 20px;}
            .accent{color:#c9a227;}

              .sl-header{padding:48px 0 28px;text-align:center;border-bottom:1px solid rgba(241,237,228,.08);position:relative;z-index:1;}
                .sl-brandmark img{height:28px;width:auto;display:block;margin:0 auto 18px;}
                  .sl-eyebrow{display:block;font-size:.76rem;letter-spacing:.14em;text-transform:uppercase;color:rgba(241,237,228,.55);margin-bottom:10px;}
                    .sl-title{font-family:'Fraunces',serif;font-weight:600;font-size:clamp(1.7rem,4.5vw,2.6rem);margin:0 0 14px;}
                      .sl-welcome{max-width:560px;margin:0 auto;color:rgba(241,237,228,.78);font-size:.98rem;white-space:pre-line;}

                        /* Pedido do usuário (22/09/2026): "e sempre coloque o maximo de animacoes em todo site possivel
                             e nessas 2 abas tambem gosto de movimento" - a aba Entregas já tinha bastante animação (zoom,
                                  manchas douradas flutuantes, entrada suave ao rolar), mas a Seleção ainda estava 100% estática
                                       (nada se mexia, nem ao carregar, nem ao passar o mouse, nem ao marcar uma foto). Adicionado
                                            aqui: as mesmas manchas douradas de fundo da Entrega, entrada em cascata da capa/título e de
                                                 cada foto ao rolar até ela, leve elevação + zoom na foto ao passar o mouse, e uma "pulsada" no
                                                      coração/botão ao marcar como favorita - pra dar a mesma sensação de movimento do resto do site. */
                                                        .sl-parallax-bg{position:fixed;inset:0;z-index:0;overflow:hidden;pointer-events:none;}
                                                          .sl-parallax-layer{position:absolute;border-radius:50%;filter:blur(70px);mix-blend-mode:screen;}
                                                            .sl-parallax-layer-1{width:42vw;height:42vw;max-width:520px;max-height:520px;top:-14%;left:-10%;background:radial-gradient(circle,rgba(201,162,39,.26),transparent 70%);animation:slParallaxDrift1 30s ease-in-out infinite;}
                                                              .sl-parallax-layer-2{width:34vw;height:34vw;max-width:440px;max-height:440px;bottom:-10%;right:-10%;background:radial-gradient(circle,rgba(255,190,90,.22),transparent 70%);animation:slParallaxDrift2 24s ease-in-out infinite;}
                                                                @keyframes slParallaxDrift1{0%,100%{transform:translate(0,0);}33%{transform:translate(7vw,5vh);}66%{transform:translate(-4vw,9vh);}}
                                                                  @keyframes slParallaxDrift2{0%,100%{transform:translate(0,0);}33%{transform:translate(-6vw,-7vh);}66%{transform:translate(4vw,-3vh);}}

                                                                    .reveal{opacity:0;transform:translateY(24px);}
                                                                      .reveal.is-visible{animation:slRevealIn .8s cubic-bezier(.16,.84,.44,1) forwards;}
                                                                        @keyframes slRevealIn{to{opacity:1;transform:none;}}

                                                                          .sl-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:14px;padding:32px 0 40px;position:relative;z-index:1;}
                                                                            .sl-card{position:relative;border-radius:10px;overflow:hidden;background:#151319;aspect-ratio:1;cursor:pointer;user-select:none;-webkit-user-select:none;transition:transform .35s cubic-bezier(.16,.84,.44,1),box-shadow .35s ease;}
                                                                              .sl-card.reveal.is-visible{animation-delay:calc(var(--sl-i,0) * 45ms);}
                                                                                .sl-card:hover{transform:translateY(-6px) scale(1.02);box-shadow:0 18px 40px rgba(0,0,0,.5);}
                                                                                  .sl-card img{width:100%;height:100%;object-fit:cover;display:block;pointer-events:none;-webkit-user-drag:none;transition:transform .6s ease;}
                                                                                    .sl-card:hover img{transform:scale(1.08);}
                                                                                      .sl-card.readonly{cursor:default;}
                                                                                        .sl-card-check{position:absolute;top:10px;right:10px;width:30px;height:30px;border-radius:50%;background:rgba(0,0,0,.55);border:2px solid rgba(255,255,255,.6);display:flex;align-items:center;justify-content:center;font-size:.95rem;padding:0;color:#fff;font-family:inherit;cursor:pointer;transition:background .2s ease,border-color .2s ease,transform .15s ease;}
                                                                                          .sl-card.is-selected .sl-card-check{background:#c9a227;border-color:#c9a227;color:#171310;transform:scale(1.08);animation:slCheckPop .45s cubic-bezier(.34,1.56,.64,1);}
                                                                                            .sl-card:active .sl-card-check{transform:scale(.92);}
                                                                                              .sl-card-zoom{position:absolute;top:10px;left:10px;width:30px;height:30px;border-radius:50%;background:rgba(0,0,0,.55);border:2px solid rgba(255,255,255,.6);display:flex;align-items:center;justify-content:center;color:#fff;padding:0;cursor:zoom-in;transition:background .2s ease,transform .2s ease;}
                                                                                                .sl-card-zoom:hover{background:rgba(0,0,0,.75);transform:scale(1.1);}
                                                                                                  .sl-card-zoom svg{width:15px;height:15px;}
                                                                                                    @keyframes slCheckPop{0%{transform:scale(.65);}60%{transform:scale(1.28);}100%{transform:scale(1.08);}}
                                                                                                    
                                                                                                      .sl-lightbox{position:fixed;inset:0;background:rgba(6,5,7,.95);display:none;align-items:center;justify-content:center;z-index:50;padding:30px;}
                                                                                                        .sl-lightbox.open{display:flex;}
                                                                                                          .sl-lightbox img{max-width:100%;max-height:88vh;border-radius:6px;}
                                                                                                            .sl-lightbox.open img{animation:slLightboxImgIn .35s cubic-bezier(.2,.8,.2,1);}
                                                                                                              @keyframes slLightboxImgIn{from{opacity:0;transform:scale(.92);}to{opacity:1;transform:scale(1);}}
                                                                                                                .sl-lightbox-close{position:absolute;top:22px;right:26px;background:none;border:0;color:#f1ede4;font-size:2rem;cursor:pointer;line-height:1;transition:transform .2s ease,color .2s ease;}
                                                                                                                  .sl-lightbox-close:hover{transform:rotate(90deg);color:#c9a227;}
                                                                                                                    .sl-lightbox-select{position:absolute;bottom:30px;left:50%;transform:translateX(-50%);background:#c9a227;color:#171310;font-weight:600;font-size:.9rem;padding:11px 26px;border-radius:100px;border:0;cursor:pointer;display:flex;align-items:center;gap:8px;transition:background .2s ease;}
                                                                                                                      .sl-lightbox-select:hover{background:#dab643;}
                                                                                                                        .sl-lightbox-select.is-selected{background:#1f8a4c;color:#fff;animation:slCheckPop .45s cubic-bezier(.34,1.56,.64,1);}
                                                                                                                          @media (max-width:640px){.sl-lightbox{padding:16px;} .sl-lightbox-select{bottom:18px;padding:10px 20px;}}
                                                                                                                          
                                                                                                                            .sl-bar{position:fixed;left:0;right:0;bottom:0;z-index:5;background:rgba(11,10,13,.94);backdrop-filter:blur(6px);border-top:1px solid rgba(241,237,228,.12);padding:14px 20px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;animation:slBarUp .6s cubic-bezier(.2,.8,.2,1);}
                                                                                                                              @keyframes slBarUp{from{transform:translateY(100%);}to{transform:translateY(0);}}
                                                                                                                                .sl-bar-count{font-size:.92rem;display:inline-block;transition:transform .25s cubic-bezier(.34,1.56,.64,1);}
                                                                                                                                  .sl-bar-count b{font-family:'Fraunces',serif;font-size:1.1rem;}
                                                                                                                                    .sl-bar-count.over{color:#e2a03f;}
                                                                                                                                      .sl-bar button{background:#c9a227;color:#171310;font-weight:600;font-size:.9rem;padding:11px 24px;border-radius:100px;border:0;cursor:pointer;white-space:nowrap;transition:background .2s ease,transform .15s ease;}
                                                                                                                                        .sl-bar button:hover:not(:disabled){background:#dab643;transform:translateY(-2px);}
                                                                                                                                          .sl-bar button:disabled{opacity:.5;cursor:default;}
                                                                                                                                            .sl-status{font-size:.85rem;color:rgba(241,237,228,.6);min-height:1.2em;}
                                                                                                                                            
                                                                                                                                              .sl-note{max-width:640px;margin:0 auto 24px;padding:0 20px;position:relative;z-index:1;}
                                                                                                                                                .sl-note label{display:block;font-size:.85rem;color:rgba(241,237,228,.65);margin-bottom:8px;}
                                                                                                                                                  .sl-note textarea{width:100%;background:#151319;border:1px solid rgba(241,237,228,.15);border-radius:8px;color:#f1ede4;font-family:inherit;font-size:.92rem;padding:12px 14px;resize:vertical;min-height:70px;transition:border-color .25s ease;}
                                                                                                                                                    .sl-note textarea:focus{outline:none;border-color:#c9a227;}
                                                                                                                                                    
                                                                                                                                                      .sl-done{max-width:520px;margin:60px auto;text-align:center;padding:0 20px;position:relative;z-index:1;}
                                                                                                                                                        .sl-done h2{font-family:'Fraunces',serif;font-weight:600;font-size:1.6rem;margin:0 0 12px;}
                                                                                                                                                          .sl-done p{color:rgba(241,237,228,.75);}
                                                                                                                                                          
                                                                                                                                                            .sl-footer{text-align:center;padding:16px 0 50px;color:rgba(241,237,228,.4);font-size:.8rem;position:relative;z-index:1;}
                                                                                                                                                              .sl-footer img{height:24px;width:auto;margin:0 auto 8px;display:block;}
                                                                                                                                                              
                                                                                                                                                                @media (prefers-reduced-motion: reduce){
                                                                                                                                                                    .sl-parallax-layer-1,.sl-parallax-layer-2,.sl-bar,.sl-card.is-selected .sl-card-check,.sl-lightbox-select.is-selected,.sl-lightbox.open img{animation:none;}
                                                                                                                                                                        .reveal{opacity:1;transform:none;}
                                                                                                                                                                            .reveal.is-visible{animation:none;}
                                                                                                                                                                              }
                                                                                                                                                                              
                                                                                                                                                                                @media (max-width:640px){.sl-grid{grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;}}
                                                                                                                                                                                `;

function pageScript(slug, limit) {
    return `
      (function(){
          var apiBase = window.NJFILMES_API_BASE || '';
              var cards = document.querySelectorAll('[data-sl-card]');
                  var countEl = document.querySelector('[data-sl-count]');
                      var statusEl = document.querySelector('[data-sl-status]');
                          var sendBtn = document.querySelector('[data-sl-send]');
                              var limit = ${JSON.stringify(limit || null)};

                                  // Pedido do usuário (22/09/2026): "coloca o maximo de animacao possivel... nessa aba tambem
                                      // gosto de movimento" - entrada em cascata da capa/título e de cada foto (".reveal") ao rolar
                                          // até elas, igual já existe na página de Entrega (server/deliveryPage.js). Aqui a página inteira
                                              // rola normal (sem div própria tipo "story"), então o observer usa a janela como referência.
                                                  (function () {
                                                        var revealEls = document.querySelectorAll('.reveal');
                                                              if (!revealEls.length) return;
                                                                    function revealAllNow() { revealEls.forEach(function (el) { el.classList.add('is-visible'); }); }
                                                                          try {
                                                                                  if ('IntersectionObserver' in window) {
                                                                                            var io = new IntersectionObserver(function (entries) {
                                                                                                        entries.forEach(function (e) {
                                                                                                                      if (e.isIntersecting) { e.target.classList.add('is-visible'); io.unobserve(e.target); }
                                                                                                                                  });
                                                                                                                                            }, { threshold: .12 });
                                                                                                                                                      revealEls.forEach(function (el) { io.observe(el); });
                                                                                                                                                                // Rede de segurança: quem já está visível assim que a página carrega (capa, primeiras
                                                                                                                                                                          // fotos da grade) às vezes não dispara o observer a tempo - mesma ideia já usada na
                                                                                                                                                                                    // Entrega, só revela quem já está mesmo dentro da tela, nunca tudo de uma vez.
                                                                                                                                                                                              [400, 1200, 3000].forEach(function (ms) {
                                                                                                                                                                                                          setTimeout(function () {
                                                                                                                                                                                                                        revealEls.forEach(function (el) {
                                                                                                                                                                                                                                        if (el.classList.contains('is-visible')) return;
                                                                                                                                                                                                                                                        var r = el.getBoundingClientRect();
                                                                                                                                                                                                                                                                        if (r.top < (window.innerHeight || 800) && r.bottom > 0) el.classList.add('is-visible');
                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                  }, ms);
                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                              revealAllNow();
                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                            } catch (err) {
                                                                                                                                                                                                                                                                                                                                                    revealAllNow();
                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                              })();
                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                  function updateCount() {
                                                                                                                                                                                                                                                                                                                                                                        var n = document.querySelectorAll('[data-sl-card].is-selected').length;
                                                                                                                                                                                                                                                                                                                                                                              if (!countEl) return;
                                                                                                                                                                                                                                                                                                                                                                                    var text = limit ? (n + ' de ' + limit + ' selecionadas') : (n + ' selecionada' + (n === 1 ? '' : 's'));
                                                                                                                                                                                                                                                                                                                                                                                          countEl.textContent = text;
                                                                                                                                                                                                                                                                                                                                                                                                countEl.classList.toggle('over', Boolean(limit) && n > limit);
                                                                                                                                                                                                                                                                                                                                                                                                      // Pequena "pulsada" no número toda vez que a contagem muda - reforço visual pra sentir que
                                                                                                                                                                                                                                                                                                                                                                                                            // marcar/desmarcar teve efeito (pedido de mais movimento, 22/09/2026).
                                                                                                                                                                                                                                                                                                                                                                                                                  countEl.style.transform = 'scale(1.25)';
                                                                                                                                                                                                                                                                                                                                                                                                                        setTimeout(function () { countEl.style.transform = 'scale(1)'; }, 220);
                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                updateCount();
                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                    // Pedido do usuário (18/09/2026): antes, clicar em qualquer parte da foto já marcava ela
                                                                                                                                                                                                                                                                                                                                                                                                                                        // como favorita, e só o ícone de lupa no canto abria a foto ampliada — só que no PC o
                                                                                                                                                                                                                                                                                                                                                                                                                                            // usuário esperava o contrário ("só abre [a foto ampliada] se clicar na seta [a lupa]").
                                                                                                                                                                                                                                                                                                                                                                                                                                                // Agora é: clicar no CORPO da foto abre ela ampliada (a lupa faz a mesma coisa, é só um
                                                                                                                                                                                                                                                                                                                                                                                                                                                    // reforço visual pra quem não sabe que a foto toda é clicável); só o coração no canto marca
                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ou desmarca como favorita diretamente na grade, sem precisar abrir a foto.
                                                                                                                                                                                                                                                                                                                                                                                                                                                            function toggleSelect(card) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (card.classList.contains('readonly')) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var photoId = card.dataset.photoId;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var willSelect = !card.classList.contains('is-selected');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    card.classList.toggle('is-selected', willSelect);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          updateCount();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fetch(apiBase + '/api/selecao-marcar/' + photoId, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        method: 'POST',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                headers: { 'Content-Type': 'application/json' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        body: JSON.stringify({ selected: willSelect }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }).catch(function () {});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.querySelectorAll('[data-sl-check]').forEach(function (checkBtn) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            checkBtn.addEventListener('click', function (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            e.stopPropagation();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var card = checkBtn.closest('[data-sl-card]');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (card) toggleSelect(card);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // "Ver foto inteira" — pedido do usuário em 17/09/2026: a grade corta a foto em quadrado
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // pra ficar organizada, mas o cliente não tinha como ver ela inteira antes de escolher. O
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // ícone de lupa (e agora também clicar em qualquer parte da foto) abre uma tela cheia com a
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // foto sem cortar (mesma marca d'água/resolução baixa de sempre) - a seleção fica só por
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // conta do coração no card ou do botão "Selecionar" de dentro da tela cheia.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var lightbox = document.querySelector('[data-sl-lightbox]');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var lightboxImg = lightbox ? lightbox.querySelector('img') : null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var lightboxSelectBtn = lightbox ? lightbox.querySelector('[data-sl-lightbox-select]') : null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var lightboxSelectLabel = lightboxSelectBtn ? lightboxSelectBtn.querySelector('[data-sl-lightbox-select-label]') : null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var zoomCard = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function refreshLightboxSelectBtn() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!lightboxSelectBtn || !zoomCard) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var isSel = zoomCard.classList.contains('is-selected');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    lightboxSelectBtn.classList.toggle('is-selected', isSel);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (lightboxSelectLabel) lightboxSelectLabel.textContent = isSel ? 'Selecionada ✓' : 'Selecionar';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Pedido do usuário (18/09/2026, mesmo ajuste feito na página de entrega): no celular, o
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // botão/gesto de "voltar" é o histórico do navegador - abrir a foto ampliada sem empilhar
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // nada nesse histórico fazia "voltar" sair da página de seleção inteira em vez de só fechar
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // a foto ampliada. Corrigido empilhando um estado falso no histórico ao abrir e fechando a
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // foto ampliada quando esse estado é desfeito (popstate).
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var lightboxHistoryPushed = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function closeLightboxVisual() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (lightbox) lightbox.classList.remove('open');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      zoomCard = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function openLightbox(card) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!lightbox || !lightboxImg) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          zoomCard = card;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var img = card.querySelector('img');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      lightboxImg.src = img ? img.src : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            refreshLightboxSelectBtn();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  lightbox.classList.add('open');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        lightboxHistoryPushed = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              history.pushState({ njLightbox: true }, '', '');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function requestCloseLightbox() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (lightboxHistoryPushed) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    history.back();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  closeLightboxVisual();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                window.addEventListener('popstate', function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (lightbox && lightbox.classList.contains('open')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              lightboxHistoryPushed = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      closeLightboxVisual();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cards.forEach(function (card) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          card.addEventListener('click', function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  openLightbox(card);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.querySelectorAll('[data-sl-zoom]').forEach(function (btn) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      btn.addEventListener('click', function (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      e.stopPropagation();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var card = btn.closest('[data-sl-card]');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (card) openLightbox(card);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (lightbox) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          lightbox.addEventListener('click', function (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (e.target === lightbox || e.target.closest('[data-sl-lightbox-close]')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            requestCloseLightbox();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (lightboxSelectBtn) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        lightboxSelectBtn.addEventListener('click', function (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                e.stopPropagation();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!zoomCard) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                toggleSelect(zoomCard);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        refreshLightboxSelectBtn();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (sendBtn) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var noteEl = document.querySelector('[data-sl-note]');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  sendBtn.addEventListener('click', function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          sendBtn.disabled = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (statusEl) statusEl.textContent = 'Enviando...';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          fetch(apiBase + '/api/selecao-enviar/' + ${JSON.stringify(slug)}, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    method: 'POST',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              headers: { 'Content-Type': 'application/json' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        body: JSON.stringify({ note: noteEl ? noteEl.value : '' }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          .then(function (r) { return r.json(); })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .then(function (data) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (data && data.ok) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              window.location.reload();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sendBtn.disabled = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (statusEl) statusEl.textContent = (data && data.error) || 'Não deu pra enviar agora. Tente de novo.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .catch(function () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  sendBtn.disabled = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (statusEl) statusEl.textContent = 'Não deu pra enviar agora. Tente de novo.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    })();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      `;
}

export function renderSelectionCasePage(selectionCase, settings = {}) {
    const c = selectionCase;
    const photos = c.photos || [];
    const isLocked = c.status === 'revisao' || c.status === 'finalizado';
    const selected = photos.filter((p) => p.selected);

  const zoomIconSvg = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7"/></svg>`;

  // "--sl-i" alimenta o atraso em cascata de cada card (".sl-card.reveal" no CSS) - repete a
  // cada 12 fotos pra não deixar a última foto de uma grade grande demorando demais pra aparecer.
  const gridHtml = (isLocked ? selected : photos)
      .map(
              (p, i) => `<div class="sl-card reveal${isLocked ? ' readonly' : ''}${p.selected ? ' is-selected' : ''}" data-sl-card data-photo-id="${p.id}" style="--sl-i:${i % 12}">
                      <img src="${escapeHtml(p.filename)}" loading="lazy" alt="">
                              <button type="button" class="sl-card-zoom" data-sl-zoom aria-label="Ver foto inteira">${zoomIconSvg}</button>
                                      ${isLocked ? '<span class="sl-card-check">✓</span>' : `<button type="button" class="sl-card-check" data-sl-check aria-label="Marcar como favorita">♥</button>`}
                                            </div>`
            )
      .join('');

  const bodyContent = isLocked
      ? `<div class="sl-done reveal">
              <h2>Seleção enviada!</h2>
                      <p>Você escolheu ${selected.length} foto${selected.length === 1 ? '' : 's'}. Já estamos editando — assim que ficar pronto, você recebe o link com as fotos finais.</p>
                              ${c.client_note ? `<p style="white-space:pre-line;"><em>Seu recado: "${escapeHtml(c.client_note)}"</em></p>` : ''}
                                    </div>
                                          ${selected.length ? `<div class="container"><div class="sl-grid">${gridHtml}</div></div>` : ''}`
        : `<div class="container">
                <div class="sl-grid">${gridHtml || '<p class="empty-hint" style="grid-column:1/-1;color:rgba(241,237,228,.5);">Nenhuma foto disponível ainda.</p>'}</div>
                      </div>
                            <div class="sl-note reveal">
                                    <label for="sl-note-input">Quer deixar algum recado? (opcional)</label>
                                            <textarea id="sl-note-input" data-sl-note rows="3" placeholder="Ex: essas 3 primeiras são pra moldura, gostaria dessa em preto e branco..."></textarea>
                                                  </div>
                                                        <div class="sl-bar">
                                                                <span class="sl-bar-count" data-sl-count></span>
                                                                        <div style="display:flex;align-items:center;gap:14px;">
                                                                                  <span class="sl-status" data-sl-status></span>
                                                                                            <button type="button" data-sl-send>Enviar seleção</button>
                                                                                                    </div>
                                                                                                          </div>`;

  return `<!DOCTYPE html>
  <html lang="pt-BR">
  <head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Seleção de fotos · ${escapeHtml(c.client_name)} · NJFILMES</title>
  <meta name="robots" content="noindex, nofollow">
  <link rel="icon" href="/img/favicon.svg" type="image/svg+xml">
  <style>${CASE_CSS}</style>
  </head>
  <body>
    <div class="sl-parallax-bg" aria-hidden="true"><div class="sl-parallax-layer sl-parallax-layer-1"></div><div class="sl-parallax-layer sl-parallax-layer-2"></div></div>
      <div class="sl-header reveal">
          <span class="sl-brandmark"><img src="/img/nj-logo.webp?v=${ASSET_VERSION}" alt="NJFILMES"></span>
              <span class="sl-eyebrow">NJ<span class="accent">FILMES</span> · Seleção de fotos</span>
                  <h1 class="sl-title">${escapeHtml(c.client_name)}</h1>
                      ${c.welcome_message ? `<p class="sl-welcome">${escapeHtml(c.welcome_message)}</p>` : '<p class="sl-welcome">Toque no coração de cada foto pra marcar como favorita — depois é só enviar. Clique na foto pra ver ela ampliada.</p>'}
                        </div>
                          ${bodyContent}
                            <div class="sl-lightbox" data-sl-lightbox>
                                <button type="button" class="sl-lightbox-close" data-sl-lightbox-close aria-label="Fechar">×</button>
                                    <img src="" alt="">
                                        ${isLocked ? '' : `<button type="button" class="sl-lightbox-select" data-sl-lightbox-select><span data-sl-lightbox-select-label>Selecionar</span></button>`}
                                          </div>
                                            <div class="sl-footer reveal">
                                                <img src="/img/nj-logo.webp?v=${ASSET_VERSION}" alt="NJFILMES">
                                                    Feito com carinho pela NJFILMES.
                                                      </div>
                                                        <script>window.NJFILMES_API_BASE = ${JSON.stringify(PUBLIC_API_BASE)};</script>
                                                          <script>${pageScript(c.slug, c.photo_limit)}</script>
                                                          </body>
                                                          </html>`;
}
